// activeRefinements already has REFINEMENT_DISALLOW_LIST filtered out (cgid is filtered
// out explicitly below, same as in applyFilters — activeRefinements itself does not
// exclude it), and reflects the pending category's live facet set when the shopper has
// changed the Category radio — so Colour shows dresses colours when Dresses is pending,
// not the old page's clothing colours.
const refinementFacetGroups: FilterFacetGroup[] = activeRefinements
  .filter(({ attributeId }) => attributeId !== 'cgid')
  .map((refinement) => {
    const selectedValues = pendingRefine[refinement.attributeId] ?? [];
    // SFCC-847 — per the design document: Size matches OOTB's own button/chip grid
    // (ZimmSizeFilter, which reuses SizeRefinements unmodified — see its own
    // docblock), every other facet uses checkbox styling (ZimmCheckboxGroup) —
    // neither routes through componentMap's own per-attribute-type dispatch (which would
    // send colour to swatches too). The OOTB sidebar and mobile modal are unaffected —
    // they still use componentMap via the base Refinements component, unchanged.
    // handleBufferedToggle (above) stands in for the page's real toggleFilter, buffering
    // into pendingRefine instead of navigating immediately. No `alwaysVisibleContent` chip
    // strip on multi-select facets — the checkbox tick itself is the selected indicator,
    // matching Figma's Colour/Material variants (audited 2026-09-16). Applied-filter chip
    // patterns as a page-level surface belong to SFCC-108 AC #6, not this ticket.
    const isSize = refinement.attributeId === SIZE_REFINEMENT_ATTRIBUTE_ID;

    return {
      id: refinement.attributeId,
      label: refinement.label ?? refinement.attributeId,
      alwaysVisibleContent:
        selectedValues.length > 0 ? (
          <Flex wrap="wrap" gap="var(--zimm-scale-2xs)">
            {selectedValues.map((value) => (
              <ZimmSelectedChip
                key={value}
                label={String(value)}
                onRemove={() => handleBufferedToggle({ value }, refinement.attributeId, true)}
              />
            ))}
          </Flex>
        ) : undefined,
      content: isSize ? (
        <ZimmSizeFilter
          filter={refinement}
          toggleFilter={handleBufferedToggle}
          selectedFilters={selectedValues}
        />
      ) : (
        <ZimmCheckboxGroup
          options={(refinement.values ?? []).map((v) => ({
            value: String(v.value),
            label: v.label ?? String(v.value),
            hitCount: v.hitCount,
            swatchColour:
              refinement.attributeId === COLOR_REFINEMENT_ATTRIBUTE_ID && v.presentationId
                ? (cssColorGroups[v.presentationId.toLowerCase()] ?? '')
                : undefined,
          }))}
          selectedValues={selectedValues}
          onChange={(value, isCurrentlySelected) =>
            handleBufferedToggle({ value }, refinement.attributeId, isCurrentlySelected)
          }
        />
      ),
    };
  });

