const {chromium} = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core');
const SP=process.env.SP;
const BASE='https://zimmermann-pr-f847-d63140d1.sfdc-8tgtt5-ecom1.exp-delivery.com';
const WIDTHS=[390,767,768,1023,1024,1439,1440];
(async()=>{
const b=await chromium.launch();
for(const w of WIDTHS){
  const p=await b.newPage({viewport:{width:w,height:900}});
  await p.goto(BASE+'/clothing/dresses',{waitUntil:'domcontentloaded',timeout:90000});
  await p.waitForTimeout(8000);
  // page-level chip strip BEFORE opening drawer
  const strip=await p.evaluate(()=>{
    const chips=[...document.querySelectorAll('[aria-label^="Remove filter"]')].map(e=>{const r=e.getBoundingClientRect();return{t:e.innerText.trim().slice(0,18),w:+r.width.toFixed(1),h:+r.height.toFixed(1)};}).filter(o=>o.w>0);
    const arrows=[...document.querySelectorAll('button')].filter(e=>/prev|next|previous/i.test(e.getAttribute('aria-label')||'')).map(e=>{const r=e.getBoundingClientRect();return{aria:e.getAttribute('aria-label'),w:+r.width.toFixed(1),h:+r.height.toFixed(1)};});
    const clearAll=[...document.querySelectorAll('button')].find(e=>/clear all/i.test(e.innerText||''));
    const ca=clearAll?(()=>{const r=clearAll.getBoundingClientRect();return{w:+r.width.toFixed(1),h:+r.height.toFixed(1)};})():null;
    return {chips,arrows,clearAll:ca};
  });
  // open drawer
  let panel=null;
  try{ await p.getByRole('button',{name:/^FILTERS$/i}).first().click({timeout:8000}); await p.waitForTimeout(1800);
    panel=await p.evaluate(()=>{const e=document.querySelector('[role=dialog]');if(!e)return null;const r=e.getBoundingClientRect();return{w:+r.width.toFixed(1),h:+r.height.toFixed(1),x:+r.x.toFixed(1)};});
  }catch(e){panel='FILTERS not found';}
  console.log(`\n=== ${w}px ===`);
  console.log(' page chips:',JSON.stringify(strip.chips),' arrows:',JSON.stringify(strip.arrows),' clearAll:',JSON.stringify(strip.clearAll));
  console.log(' drawer panel:',JSON.stringify(panel));
  await p.screenshot({path:`${SP}/shots/drawer-${w}.png`});
  await p.close();
}
await b.close();
})().catch(e=>{console.error('ERR',e.message);process.exit(1);});
EOF
